    var strVar="";
    strVar += "     ";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 据CTR最新发布的中国广告花费数据显示，2010年全年广告花费增幅最终未能达到各方预测，落在13%。<\/div>";
    strVar += "<div>&nbsp;<\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 2011年中国社会通胀预期较为强烈，对于经济发展可能形成一定压力，在此情况下，作为社会经济发展\"风向标\"的广告市场同样可能受到影响。不过，根据过往几年的实际广告投放经验，以及各经济研究机构对于2011年中国GDP增速的预测，CTR仍预测2011年中国广告市场仍将领先GDP增长保持15%左右的增幅。<\/div>";
    strVar += "<div>&nbsp;<\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; &nbsp;\"61号令\"后电视广告经营进入变革时代，传统媒体市场出现广告投放\"分流\"局面。电视媒体广告11%的增幅首次落后全媒体增幅， 且占投放市场份额下降至76%，但电视媒体在进行广告资源的进一步优化后，广告收入呈现\"价值驱动上升\"，稀缺资源受到进一步追捧，强势卫视广告经营能力增强。&nbsp;<br><\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 电台媒体全年增幅最大，同比增长33%，这一方面受益于政策影响，同时也受益于对资源量的扩容，19%的增幅是众媒体中资源量扩容最大的媒体形式。<\/div>";
    strVar += "<div>&nbsp;<\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 同样进行资源扩容的还有平面报纸和杂志，2010年全年分别比去年同期扩容了11%和6%，收入增长却是相同，同为19%。&nbsp;<\/div>";
    strVar += "<div>&nbsp;<\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 八大行业对广告行业的增长提供重要贡献，其中贡献最大的前三大行业分别是化妆品\/浴室用品3% 、交通2% 、饮料1.9%。交通行业首次成为广告增长最快的行业，增幅达44%，而娱乐及休闲（22%）、活动类行业（23%）快速增长，从一个侧面揭示2010年市场\"娱乐盛行\"。<\/div>";
    strVar += "<div>&nbsp;<\/div>";
    strVar += "<div>&nbsp;&nbsp;&nbsp; 往年投放火热的保健品，全年广告投放大幅减少，拉低食品行业投放多年来首次出现负增长（下降0.5%），首次跌入广告投放降幅最大的TOP5行业。从行业与媒体的双重角度来看，商业及服务性行业取代房地产成为户外广告主要来源；交通行业对于电台媒体投放依赖性增强；国际奢侈品杂志广告投放增加；家电零售、建材卖场、房地产领军企业报纸投放大幅提升。&nbsp;<\/div>";
