var pd2010newsStr = function(){
    var strVar="";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; <strong>看点一：整体环境 <\/strong><\/font><\/div>";
    strVar += "<div><strong><\/strong><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年，我国经济运行态势良好，户外广告市场呈现稳步增长势头。<\/font><\/div>";
    strVar += "<div><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年我国经济保持了平稳较快增长，在良好的大气候下，户外广告市场也呈现了较快增长。今年前11月户外广告投放总额达到395亿元，已超过去年全年投放额的13%。排除收集范围和刊例价格变动，前11月户外广告投放净值已高于去年全年。预计今年全年户外广告投放额有望达到430亿元，同比增长20%左右。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; <strong>看点二：大事件中的户外广告 <\/strong><\/font><\/div><strong><\/strong>";
    strVar += "<div><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 精彩纷呈的世博会、激情四溢的世界杯、鼓舞人心的广州亚运会，这些盛事让2010年变得非比寻常。每一个盛事都成为国际国内品牌角逐的竞技场，赞助商与非赞助商的博弈甚嚣尘上，让户外广告也变得越来越精彩。<\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; <\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp;&nbsp;运动品牌营销大战 <br>&nbsp;&nbsp;&nbsp; 本届南非世界杯球衣的品牌赞助商仅有7个。其中，三大运动品牌阿迪达斯、耐克和彪马共赞助了28支球队，集中度之高令人咋舌。为应对来自耐克日趋激烈的竞争，为保住“足球第一品牌”的宝座，阿迪达斯重金赞助了阿根廷、西班牙、德国和东道主南非等三分之一的世界杯参赛球队，并赞助了本届世界杯整个赛事。<\/font><\/div>";
    strVar += "<div><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 中天数据显示，2010年前5个月共有61个品牌投放了运动系列产品广告。其中，阿迪达斯、耐克、李宁和彪马四个品牌就占据了81%的市场份额。国内知名运动品牌李宁虽不是世界杯赞助商，但其户外广告投放表现强势。据各家财报统计，目前耐克、李宁和阿迪达斯分占中国销售额三甲。<\/font><\/div>";
    strVar += "<div><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 中国足球进不了世界杯，但不代表中国企业进不了世界杯，不影响中国球迷对“普天同庆”的足球盛宴的热情，并形成有中国特色的世界杯经济效应。各大国际品牌都越来越重视中国消费市场，国内品牌也不示弱地镇守领地，在世界杯期间通过各种媒介打响品牌争夺战。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><img title=\"\" height=\"199\" alt=\"\" src=\"http:\/\/www.towona.com\/images\/data\/shijiebei.jpg\" width=\"265\"><\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; <\/font><\/div>";
    strVar += "<div><strong><font size=\"4\">啤酒的世界杯营销<\/font><\/strong><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\"><strong>&nbsp;&nbsp;&nbsp; <\/strong>一直以来，啤酒终端市场竞争都非常激烈，世界杯的开赛更是为这场啤酒之战添了一把火。百威英博利用“世界杯官方合作伙伴”身份将哈尔滨啤酒带入了世界杯赛场，场馆的中文广告让中国球迷惊讶又自豪了一把；与此同时，国内的雪花、青岛、燕京也不甘示弱，燃起了一场规模空前的啤酒大战。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 在其他领域，无论世界杯赞助商还是非赞助商也都纷纷加入了世界杯营销，麦当劳与肯德基、可口可乐与百事可乐，索尼与其他电视品牌等表现尤为抢眼，四年一届全世界都热衷的体育盛事，如何能错过！ <\/font><\/div>";
    strVar += "<p><br><font size=\"4\"><strong>世博会（邮电通讯和银行行业）<\/strong> <\/font><\/p>";
    strVar += "<p><font size=\"4\">&nbsp;&nbsp;&nbsp; 三大运营商的对决 <br>&nbsp;&nbsp;&nbsp; 对于大事件营销，中国移动、中国电信、中国联通的对决最为激烈。在上海世博会召开前后，三大运营商不遗余力大张旗鼓的展开营销活动，营销内容主要集中在通信保障、移动支付、客户服务和创新业务四个方面。其中，移动支付成为市场争夺的焦点。<\/font><\/p>";
    strVar += "<p><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年前5月银行信用卡类户外广告受中国工商银行、中国银行和广东发展银行广告同比紧缩的影响，投放量同比下滑26%。而作为上海世博会商业银行全球合作伙伴的交通银行，广告投放比较活跃，广告支出已由去年同期的第六位跃升至首位。 <\/font><\/p>";
    strVar += "<p><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 交通银行借世博发力 <br>&nbsp;&nbsp;&nbsp; 交通银行作为世博金融类唯一合作伙伴，专属权利是在世博场馆内，所有金融类服务都由交通银行来提供。但事实上，各家银行都卯足了劲希望分得一杯羹。朗朗作为世博的形象代言人之一，也是招商银行的形象代言人，招行正想尽办法，希望朗朗在世博宣传中力挺招行。<\/font><\/p>";
    strVar += "<p><font size=\"4\">&nbsp;&nbsp;&nbsp; 亚运会（汽车、运动和邮电通讯行业） <br>&nbsp;&nbsp;&nbsp; 52家赞助商、近30亿元的赞助金额——亚运的赞助记录被刷新。后奥运时代，广州亚运会无疑成为企业提升品牌、走向国际市场的最佳营销平台，赞助商各类企业云集、结构多元多样，大行体育营销战略。国内相关行业龙头企业以及广东本土企业成为本届亚运赞助商的主力：广汽赞助费达6亿，361°3.5亿。 <\/font><\/p>";
    strVar += "<p><br><font size=\"4\">&nbsp;&nbsp;&nbsp; 广汽：家门口的营销盛宴 <br>&nbsp;&nbsp;&nbsp; 广汽集团早在2008年就已签约成为广州亚运会高级合作伙伴，为本市的这一体育盛事砸下6亿的赞助金，包括3亿元现金和向亚运会提供亚运交通服务车辆，这一数量达到1778辆，其中包括500辆广汽首款自主品牌乘用车传祺。 <br>&nbsp;&nbsp;&nbsp; 户外广告投放领域，广汽集团加大了集团品牌的户外投放力度，其旗下品牌广汽丰田、广汽本田、广汽日野在2010年的户外投入都有一定幅度的上涨。广汽集团及其旗下品牌户外投放明显倾向于一线城市，其中北上广占户外花费整体份额的80%左右。集团和其自主品牌乘用车目前只在北上广三市投放有户外广告。<\/font><\/p>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 361°vs安踏：布局亚洲之争 <br>&nbsp;&nbsp;&nbsp; 361°此次斥资3.5亿元赞助广州亚运会，成为赞助商中唯一的运动品牌，即是迈出国门布局亚洲版图的第一步。据悉，此后361°将计划赞助2011年世界大学生运动会、2012年亚洲沙滩运动会、2013年亚洲青年运动会、2014年韩国仁川亚运会等亚洲顶级体育赛事，展开体育营销战略。 <br>&nbsp;&nbsp;&nbsp; 广告宣传方面，361°侧重于电视与网络媒体的广告宣传，并没有在户外投放策略方面太多动作，同比去年户外投放总额有15%的增长。在邻近亚运期间， 户外投放还呈现走低的曲线。相对于361°在户外领域的无动作，作为同级品牌竞争对手的安踏，在亚运前夕以及亚运期间发力户外投放，10月和11月分别同比上涨10倍和44倍。 <br>&nbsp;&nbsp;&nbsp; <\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 2009年7月，网易开始发力投入户外广告宣传，在2010年一、二季度有一个爆发性的投入曲线，宣传其亚运互联网合作伙伴的身份，效果显著。<\/font><\/div>";
    strVar += "<p><font size=\"4\">&nbsp;&nbsp;&nbsp; 但和奥运会、世博会一样，亚运会也带来了广州的户外广告整治。亚运会开幕之前，广州市政府发文明确拆迁整顿户外广告牌，对违法和过期广告牌进行拆迁，建筑物屋顶广告牌全面清拆，8月、9月、10月广州市户外广告经历了一次全面清理。亚运期间即11月1日-12月19日广州市内多个商区、街道、场馆区户外广告投放被临时管控，只允许广州亚运相关公益广告及亚运会赞助企业的广告宣传。 <\/font><\/p>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp;<strong> 看点三：LED市场竞争日益激烈，传统户外媒体公司涉足LED <\/strong><br>&nbsp;&nbsp;&nbsp; <\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年1-11月LED市场投放总额已达65.5亿元，同比增长104%！如此快速规模的发展也让LED市场竞争显得更加激烈。&nbsp;<br><\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; &nbsp;LED媒体的老牌经营者郁金香和香榭丽，与新秀凤凰传媒继续PK，而后者凭借着快速扩张的理念和魄力，加之雄厚资本的支持，屏幕数量已达到45块，投放额相比去年同期翻倍增长，可以说在2010年的市场博弈中取得了阶段性胜利。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 在市场圈地基本完成后，LED媒体评估、媒体投放效果成为不能回避的问题。2010年LED市场另一个特点是媒体公司更加重视自身媒体效果调研，为每块屏做单点位媒体价值研究，为大客户提供广告发布后效果调研。第三方公司也和媒体公司一起努力，建立区别于传统户外媒体研究模式和电视媒体研究模式，为LED媒体量身定做一套效果调研体系。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年，电信传媒也在户外行业越来越多的发出自己的声音，他们号称是全国分布城市数量最广，资源最多的LED联播网。一些传统户外媒体的经营者，不论是专注于公交巴士领域的企业，亦或是主营单一大牌的企业，纷纷开始加入到LED阵营中，或是用高科技对LED进行改造，让LED变得更节能、更环保、使用寿命延长，运营成本降低。在不久的将来，可以预见，随着参与公司的不断增加，LED市场会变得越发热闹起来。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><strong><font size=\"4\">&nbsp;&nbsp;&nbsp; 看点四：传统户外媒体公司加快布局调整<\/font><\/strong><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\"><strong>&nbsp;&nbsp;&nbsp; <\/strong>分众斥资6100万美元买入华视1533万股普通股，无疑成为2011年户外行业新年又一重磅新闻。分众传媒董事长江南春表示，“华视的公共交通系统移动电视网络与分众的楼宇、住宅、大卖场和超市电视网络及影院网络具有很强的优势互补性，我们认为这将创造机会为我们的广告客户提供全方位的传播方案和更大的传播价值。”&nbsp;<br><\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; &nbsp;一线城市龙头企业的布局在09年金融危机之前基本已经完成。有业内人士表示，金融危机让一部分竞争性差的户外企业遭到淘汰，而有竞争优势的企业则继续努力生存。金融危机后，户外行业又迎来了资本重置、调整市场布局的最好时代。&nbsp;<br><\/font><\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; &nbsp;2010年，处在户外第二梯队的户外媒体公司，尤其是二三线城市的龙头企业都在加快布局，向更多领域拓展业务。比如大贺传媒近来频频主推物联网业务，这是一种类似于维络城的广告机，但比维络城延展了很多新的功能；如重庆的大牌被拆得七七八八后，重庆传统媒体企业开始联合开展21城的业务，在迅速联合或并购二三线城市公司，开展电梯框架媒体业务。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年，地铁媒体格局也出现大震动。深圳地铁招标结束，深圳报业竞标成功，2011年开始代替天骏传媒经营深圳地铁。新秀百骏地铁拿下业内本来不太看好的成都地铁，用火爆的销售业绩证明了占领成都地铁的正确性。北京地铁4号线租金成本逐年提高，也带来2011年地铁经营的重新竞标。刚刚开通的北京地铁大兴线也在进行激烈的竞标。&nbsp;<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; &nbsp;2010年，户外是被大事件渲染围绕的一年；无论是稳守优势山头，还是涉足新的领域，2010年可以说是户外的小丰收年，户外投放总额又达到了新高。<\/font><\/div>";
    strVar += "<div><font size=\"4\"><\/font>&nbsp;<\/div>";
    strVar += "<div><font size=\"4\">&nbsp;&nbsp;&nbsp; 2010年，你收获了么？2011年，我们准备好了吗？<br><\/font><\/div>";
    return strVar;
  }
